// Summarise what is about to happen, in the words the approver needs.
// "Approve action?" with no detail trains people to click Approve.
return $input.all().map((item) => {
  const d = item.json.body ?? item.json;
  return {
    json: {
      ...d,
      summary: [
        `*Action:* ${d.action ?? 'unspecified'}`,
        `*Target:* ${d.target ?? 'unspecified'}`,
        `*Value:* ${d.amount ?? d.value ?? 'n/a'}`,
        `*Requested by:* ${d.requested_by ?? 'automation'}`,
      ].join('\n'),
    },
  };
});
